export const CARDS = [
['pitch','Elevator Pitch','skill',1,6,0,0,'Deal 6 progress.'],['breathe','Deep Breath','care',1,0,6,0,'Gain 6 composure.'],['follow','Quick Follow-up','network',0,3,0,0,'Deal 3 progress. Draw 1.',{draw:1}],['portfolio','Side Project','skill',2,13,0,0,'Deal 13 progress.'],['coffee','Coffee Chat','network',1,4,4,0,'Deal 4 progress. Gain 4 composure.'],['referral','Employee Referral','network',2,16,0,0,'Deal 16 progress.'],['tests','Write the Tests','skill',1,5,5,0,'Deal 5 progress. Gain 5 composure.'],['boundary','Set Boundaries','care',1,0,10,0,'Gain 10 composure.'],['nap','Power Nap','care',1,0,3,5,'Restore 5 confidence. Gain 3 composure.'],['debug','Rubber Duck','skill',0,0,0,0,'Draw 2 cards.',{draw:2}],['viral','Thought Leader','network',1,7,0,0,'Deal 7 progress. Draw 1.',{draw:1}],['leetcode','LeetCode Grind','skill',2,20,0,-3,'Deal 20 progress. Lose 3 confidence.'],['star','STAR Story','network',1,8,3,0,'Deal 8 progress. Gain 3 composure.'],['scope','Clarify the Scope','care',1,0,5,0,'Gain 5 composure. Weaken pressure by 3.',{weak:3}],['deploy','Ship It','skill',3,27,0,0,'Deal 27 progress.'],['intro','Warm Introduction','network',1,9,0,0,'Deal 9 progress.'],['water','Hydrate','care',0,0,3,2,'Gain 3 composure. Restore 2 confidence.'],['rewrite','Résumé Rewrite','skill',1,5,0,0,'Deal 5 progress. Gain 1 energy.',{energy:1}],['research','Company Research','skill',1,0,4,0,'Gain 4 composure. Draw 2.',{draw:2}],['salary','Salary Anchor','network',2,12,8,0,'Deal 12 progress. Gain 8 composure.'],['walk','Touch Grass','care',2,0,8,10,'Restore 10 confidence. Gain 8 composure.'],['open','Open Source','skill',1,10,0,0,'Deal 10 progress.'],['ask','Ask a Friend','network',0,0,0,0,'Gain 1 energy. Draw 1.',{energy:1,draw:1}],['mentor','Mentor Session','care',1,0,7,3,'Gain 7 composure. Restore 3 confidence.'],['whiteboard','Whiteboard Wizard','skill',2,15,4,0,'Deal 15 progress. Gain 4 composure.'],['negotiate','Negotiate','network',2,18,0,0,'Deal 18 progress. Weaken pressure by 2.',{weak:2}],['focus','Focus Mode','skill',1,0,0,0,'Next progress card gains +8.',{boost:8}],['silence','Mute Notifications','care',1,0,8,0,'Gain 8 composure. Weaken pressure by 2.',{weak:2}],['network','Alumni Network','network',2,10,0,0,'Deal 10 progress. Draw 2.',{draw:2}],['senior','Staff Energy','skill',3,22,10,0,'Deal 22 progress. Gain 10 composure.']
].map(([id,name,type,cost,damage,block,heal,text,extra={}])=>({id,name,type,cost,damage,block,heal,text,...extra}));
export const card = id=>CARDS.find(c=>c.id===id);
export const ACTS=['The Application Void','The Interview Gauntlet','The Offer Mirage'];
const bosses=[['The ATS Gatekeeper','“Please upload your résumé. Now type it again.”',40,8,1],['The Technical Interview','“Reverse a linked list. Without a keyboard.”',62,11,3],['The Offer Committee','“One final round. For real this time.”',88,14,4]];
const foes=[['Ghost Recruiter','“Love your profile! Can you hop on a call?”',25,6,2],['The Job Listing','“Entry level. 10 years of Kubernetes.”',29,7,1],['Take-home Assignment','“Should only take a weekend.”',37,9,3],['Culture Fit Panel','“We work hard and play mandatory ping-pong.”',40,9,2],['The Budget Freeze','“The role is approved. The budget is not.”',49,11,4],['Reference Check','“Can we call your manager? Today?”',53,12,2]];
export const fresh=()=>({version:1,meta:{xp:0,runs:0,wins:0,upgrades:0},run:null});
export function validSave(s){
 const integer=(n,min=0,max=1000000)=>Number.isInteger(n)&&n>=min&&n<=max;
 const ids=a=>Array.isArray(a)&&a.length<=500&&a.every(id=>card(id));
 if(s?.version!==1||!s.meta||!['xp','runs','wins','upgrades'].every(k=>integer(s.meta[k]))||s.meta.upgrades>6)return false;
 const r=s.run;if(r===null)return true;if(!r||!['map','combat','reward','lost','won'].includes(r.phase))return false;
 if(!ids(r.deck)||!ids(r.hand)||!ids(r.draw)||!ids(r.discard)||!ids(r.rewards)||r.hand.length>10)return false;
 if(!integer(r.hp,-100,100)||!integer(r.maxHp,60,90)||r.hp>r.maxHp||!integer(r.stage,0,9)||!integer(r.turn,1)||!['block','energy','boost','weak','earned'].every(k=>integer(r[k])))return false;
 if(!Array.isArray(r.log)||r.log.length>5||!r.log.every(t=>typeof t==='string'&&t.length<=500))return false;
 if(r.phase==='combat'&&(!r.enemy||r.stage>=9||!integer(r.enemy.hp,1,100)||!integer(r.enemy.maxHp,1,100)||!integer(r.enemy.attack,0,30)||!integer(r.enemy.sprite,0,5)||typeof r.enemy.boss!=='boolean'||!['name','quote'].every(k=>typeof r.enemy[k]==='string'&&r.enemy[k].length<=200&&!/[<>]/.test(r.enemy[k]))))return false;
 return true;
}
export function shuffle(arr,rng=Math.random){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
export function start(s){const maxHp=60+s.meta.upgrades*5;s.run={phase:'map',stage:0,hp:maxHp,maxHp,deck:['pitch','pitch','pitch','pitch','breathe','breathe','breathe','follow','coffee','portfolio'],hand:[],draw:[],discard:[],block:0,energy:3,boost:0,weak:0,turn:1,enemy:null,rewards:[],log:['A fresh résumé. A fresh dose of optimism.'],earned:0};s.meta.runs++;}
function log(r,t){r.log=[t,...r.log].slice(0,5)}
export function draw(r,n){for(let i=0;i<n;i++){if(!r.draw.length){r.draw=shuffle(r.discard);r.discard=[]}if(r.draw.length&&r.hand.length<10)r.hand.push(r.draw.pop())}}
export function encounter(s,choice){const r=s.run;if(r.phase!=='map')return;const boss=r.stage%3===2;if(!boss&&choice==='rest'){r.hp=Math.min(r.maxHp,r.hp+12);log(r,'Closed the laptop. Restored 12 confidence.');r.stage++;return}if(!boss&&choice==='event'){const id=shuffle(CARDS.filter(c=>c.type==='network'))[0].id;r.deck.push(id);r.hp=Math.max(1,r.hp-4);log(r,`Networking mixer: gained ${card(id).name}. Small talk cost 4 confidence.`);r.stage++;return}
const data=boss?bosses[Math.floor(r.stage/3)]:foes[Math.floor(r.stage/3)*2+r.stage%3];const [name,quote,maxHp,attack,sprite]=data;r.enemy={name,quote,hp:maxHp,maxHp,attack,sprite,boss};r.phase='combat';r.hand=[];r.draw=shuffle(r.deck);r.discard=[];r.block=0;r.energy=3;r.boost=0;r.weak=0;r.turn=1;draw(r,5);log(r,`${name} enters the chat.`);}
export const pressure=r=>Math.max(0,r.enemy.attack+(r.turn%3===0?4:0)-r.weak);
function finish(s,won){const r=s.run;r.phase=won?'won':'lost';const xp=r.earned+(won?30:8);s.meta.xp+=xp;if(won)s.meta.wins++;log(r,`${won?'Offer secured':'This run ends here'}. Earned ${xp} experience.`)}
export function play(s,index){const r=s.run;if(r.phase!=='combat')return false;const c=card(r.hand[index]);if(!c||c.cost>r.energy)return false;r.hand.splice(index,1);r.energy-=c.cost;r.discard.push(c.id);const damage=c.damage+(c.damage?r.boost:0);if(c.damage)r.boost=0;r.enemy.hp-=damage;r.block+=c.block;r.hp=Math.min(r.maxHp,r.hp+c.heal);r.weak+=c.weak||0;r.boost+=c.boost||0;r.energy+=c.energy||0;draw(r,c.draw||0);log(r,`${c.name}${damage?`: +${damage} progress`:''}.`);if(r.hp<=0){finish(s,false)}else if(r.enemy.hp<=0){r.earned+=r.enemy.boss?15:8;r.stage++;if(r.stage>=9)finish(s,true);else{r.phase='reward';r.rewards=shuffle(CARDS).slice(0,3).map(c=>c.id);log(r,'Advanced to the next round. Draft a card.')}}return true;}
export function endTurn(s){const r=s.run;if(r.phase!=='combat')return;const hit=Math.max(0,pressure(r)-r.block);r.hp-=hit;log(r,hit?`Interview pressure costs ${hit} confidence.`:'You handled the pressure.');if(r.hp<=0){finish(s,false);return}r.discard.push(...r.hand);r.hand=[];r.block=0;r.energy=3;r.boost=0;r.weak=0;r.turn++;draw(r,5)}
export function reward(s,id){const r=s.run;if(r.phase!=='reward')return;if(id!==null&&!r.rewards.includes(id))return;if(id){r.deck.push(id);log(r,`${card(id).name} joins your deck.`)}r.phase='map';r.rewards=[]}
export function upgrade(s){const cost=25+s.meta.upgrades*15;if(s.run&&!['won','lost'].includes(s.run.phase))return false;if(s.meta.xp<cost||s.meta.upgrades>=6)return false;s.meta.xp-=cost;s.meta.upgrades++;return true;}
